/* eslint-env amd */
define([], function() {
    'use strict';

    function create(root, selectors) {
        return {
            searchUrl: root.getAttribute('data-search-url'),
            emptyLabel: root.getAttribute('data-empty-label') || 'No results',
            errorLabel: root.getAttribute('data-error-label') || 'Search error',
            loadingLabel: root.getAttribute('data-loading-label') || 'Loading…',
            trigger: root.querySelector(selectors.trigger),
            modal: root.querySelector(selectors.modal),
            input: root.querySelector(selectors.input),
            results: root.querySelector(selectors.results),
            backdrop: root.querySelector(selectors.backdrop),
            closeButton: root.querySelector(selectors.close),
            controller: null,
            debounceTimer: null,
            activeIndex: -1,
            items: [],
            lastQuery: '',
            initialLabel: root.getAttribute('data-initial-label') || 'Start typing to search',
            rememberedQuery: '',
            previousFocus: null,
            bestLabel: root.getAttribute('data-best-label') || 'Best',
            recentLabel: root.getAttribute('data-recent-label') || 'Recent',
            favoriteLabel: root.getAttribute('data-favorite-label') || 'Favorites',
            isOpening: false,
            globalShortcutBound: false,
            favoriteTitle: root.getAttribute('data-favorite-title') || 'Toggle favorite',
            clearRecentLabel: root.getAttribute('data-clear-recent-label') || 'Clear recent',
            resultIdPrefix: 'campusfr-command-result-' + Math.random().toString(36).slice(2),
            executeUrl: root.getAttribute('data-execute-url'),
            confirmLabel: root.getAttribute('data-confirm-label') || 'Confirm',
            cancelLabel: root.getAttribute('data-cancel-label') || 'Cancel',
            actionErrorLabel: root.getAttribute('data-action-error-label') || 'Action error',
            actionFailedLabel: root.getAttribute('data-action-failed-label') || 'Action failed',
            isExecuting: false,
            activeMenuIndex: -1,
            activeMenuItemIndex: -1,
            executingItemKey: '',
            pendingAction: null,
            dialog: null,
            dialogTitle: null,
            dialogMessage: null,
            dialogConfirm: null,
            dialogCancel: null,
            previousDialogFocus: null,
            notification: null,
            notificationTimer: null,
            dangerConfirmLabel: root.getAttribute('data-danger-confirm-label') || 'Confirm action',
            menuActionsLabel:
                root.getAttribute(
                    'data-menu-actions-label'
                ) || 'Result actions',

            dialogLabel:
                root.getAttribute(
                    'data-dialog-label'
                ) || 'Action confirmation'
        };
    }

    function isValid(state) {
        return !!(state.trigger && state.modal && state.input && state.results);
    }

    return {
        create: create,
        isValid: isValid
    };
});